:root{font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang SC",system-ui,sans-serif;font-size:13px;line-height:1.45;color:var(--od-ink);background:var(--od-bg);color-scheme:light}
*{box-sizing:border-box}
[hidden]{display:none!important}
body{display:flex;flex-direction:column;margin:0;background:var(--od-bg)}
input,select,textarea{width:100%;min-width:0;border:1px solid var(--od-input-border);border-radius:var(--radius-control);background:var(--od-paper);color:var(--od-ink);font:inherit;padding:var(--space-2) var(--space-3)}
input,select{min-height:36px}
input[type=checkbox]{width:auto;min-height:0;margin-right:6px}
textarea{display:block;margin:var(--space-2) 0 var(--space-3);font:var(--od-note-size)/1.55 ui-monospace,SFMono-Regular,Consolas,monospace;resize:vertical;tab-size:2}
button{max-width:100%;border:0;border-radius:var(--radius-control);background:var(--od-brand);color:var(--od-on-brand);padding:var(--space-2) var(--space-3);min-height:34px;font:inherit;cursor:pointer;overflow-wrap:anywhere}
button:disabled{opacity:.48;cursor:not-allowed}
button:hover:not(:disabled){filter:brightness(.97)}
:focus-visible{outline:2px solid var(--od-focus);outline-offset:2px}
@media(prefers-color-scheme:dark){
  :root{color-scheme:dark}}
/* Shared primitives: semantics here; state-specific geometry stays in tool-shell.css. */
.od-page{min-width:0}
.od-toolbar{display:flex;align-items:center;gap:var(--space-2);min-width:0}
.od-page-head{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2);min-height:var(--od-icon-size);min-width:0}
.od-page-title{min-width:0;margin:0;color:var(--od-ink);font-size:var(--od-note-size);font-weight:600;line-height:1.5;overflow-wrap:anywhere}
.od-page-actions{display:flex;align-items:center;justify-content:flex-end;gap:var(--space-2);min-width:0;flex:none;margin-inline-start:auto}
/* Tools Index/Detail is the trusted Tab header baseline; narrow actions wrap as a group. */
@media(max-width:240px){.od-page-head{flex-wrap:wrap}.od-page-actions{flex-wrap:wrap;max-width:100%}}
.od-stack{display:grid;gap:var(--space-2);min-width:0}
/* Public component contract: semantic appearance lives only here; pages own layout. */
.od-surface{min-width:0;background:var(--od-paper);border:1px solid var(--od-line);border-radius:var(--radius-surface)}
.od-surface--padded{padding:var(--space-3)}
.od-button{display:inline-flex;align-items:center;justify-content:center;gap:var(--space-1);max-width:100%;min-height:36px;padding:var(--space-2) var(--space-3);font:inherit;font-weight:650;border:1px solid var(--od-brand);border-radius:var(--radius-control);background:var(--od-brand);color:var(--od-on-brand);text-align:center}
.od-button--secondary{background:var(--od-action-bg);border-color:var(--od-action-border);color:var(--od-action-ink)}
.od-button--danger{background:var(--od-negative-bg);border-color:var(--od-negative);color:var(--od-negative)}
.od-button--quiet{background:transparent;border-color:transparent;color:var(--od-ink)}
/* Opt-in compact navigation tab: shared focus/disabled semantics, no tool-private button skin. */
.od-button--tab{min-height:0;padding:0;border:0;border-radius:0}
.od-icon-button{position:relative;display:inline-grid;place-items:center;flex:none;width:var(--od-icon-size);height:var(--od-icon-size);min-width:var(--od-icon-size);min-height:var(--od-icon-size);padding:0;border:1px solid var(--od-line);border-radius:var(--radius-control);background:var(--od-paper);color:var(--od-sub)}
.od-icon-button--primary{border-color:var(--od-brand);background:var(--od-brand);color:var(--od-on-brand)}
.od-icon-button--danger{border-color:var(--od-negative);background:var(--od-negative-bg);color:var(--od-negative)}
/* Opt-in unframed icon action for compact product toolbars.
   Keeps the trusted 34px hit target, focus, disabled and danger semantics. */
.od-icon-button--quiet{border-color:transparent;background:transparent}
.od-icon-button--quiet:hover:not(:disabled){border-color:transparent;background:var(--od-muted)}
.od-icon-button--quiet[aria-expanded=true]{border-color:transparent}
.od-icon-button svg{width:18px;height:18px;display:block;pointer-events:none;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.od-icon-button:hover:not(:disabled):not(.od-icon-button--primary):not(.od-icon-button--danger){background:var(--od-muted)}
.od-icon-button[aria-expanded=true]{background:var(--od-muted);border-color:var(--od-focus);color:var(--od-accent-ink)}
/* R40: Tool/Page header actions are ghost by default; hit targets remain 34px.
   Only hover, focus and expanded state receive a subtle surface. */
.od-page-head .od-icon-button{border-color:transparent;background:transparent;color:var(--od-sub)}
.od-page-head .od-icon-button--primary{color:var(--od-brand)}
.od-page-head .od-icon-button:hover:not(:disabled){border-color:transparent;background:var(--od-muted);color:var(--od-ink)}
.od-page-head .od-icon-button[aria-expanded=true]{border-color:transparent;background:var(--od-muted);color:var(--od-accent-ink)}

:is(input,select,textarea).od-field{min-width:0;border:1px solid var(--od-input-border);border-radius:var(--radius-control);background:var(--od-paper);color:var(--od-ink);font-size:var(--od-body-size)}
