.od-disclosure>summary :is(strong,b){font-size:inherit;font-weight:inherit;color:inherit}
.od-disclosure[open]>summary{border-bottom:1px solid var(--od-line)}
/* One hover contract for every trusted first-level disclosure. */
.od-disclosure>summary:hover{background:var(--od-muted)}
.od-disclosure:not([open])>summary:hover{border-radius:var(--radius-surface)}
.od-disclosure[open]>summary:hover{border-radius:var(--radius-surface) var(--radius-surface) 0 0}
